function validate(input) {
  const [arr, steps, startIndex] = input;
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 10000) return 'arr needs 1 to 10^4 values.';
  if (!arr.every((value) => Number.isInteger(value) && value >= -10000 && value <= 10000)) return 'Each value of arr is an integer from -10^4 to 10^4.';
  if (!Array.isArray(steps) || steps.length < 1 || steps.length > 100) return 'steps needs 1 to 100 jumps.';
  if (!steps.every((jump) => Number.isInteger(jump) && jump >= -10000 && jump <= 10000)) return 'Each jump is an integer from -10^4 to 10^4.';
  if (!Number.isInteger(startIndex) || startIndex < 0 || startIndex >= arr.length) return 'startIndex must be a valid index of arr.';
  return null;
}

