function adapt(input, solve, kit) {
  const [arr, steps, startIndex] = input;
  const gen = solve(arr, startIndex);
  if (!gen || typeof gen.next !== 'function') throw new Error('cycleGenerator must return a generator object.');
  kit.trace(`cycleGenerator(arr, ${startIndex}) creates the generator`);
  const values = [];
  const take = (jump) => {
    const step = jump === undefined ? gen.next() : gen.next(jump);
    if (!step || typeof step !== 'object' || !Number.isInteger(step.value)) throw new Error('Each next() call must produce an element of arr as its value.');
    if (step.done) throw new Error('The generator finished early; it should never finish.');
    kit.trace(`gen.next(${jump === undefined ? '' : jump}) yields ${step.value}`);
    values.push(step.value);
  };
  take(undefined);
  for (const jump of steps) take(jump);
  return values;
}

