  // Walk one place at a time, wrapping at the ends, as the rules describe it.
  let position = startIndex;
  let jump = yield arr[position];
  for (;;) {
    for (let k = 0; k < Math.abs(jump); k++) {
      if (jump > 0) position = position === arr.length - 1 ? 0 : position + 1;
      else position = position === 0 ? arr.length - 1 : position - 1;
    }
    jump = yield arr[position];
