function generate(rand, size) {
  const small = size === 'small';
  const length = small ? 1 + Math.floor(rand() * 6) : 1000 + Math.floor(rand() * 1001);
  const spread = small ? 10 : 10000;
  const arr = Array.from({ length }, () => Math.floor(rand() * (2 * spread + 1)) - spread);
  const count = small ? 1 + Math.floor(rand() * 8) : 100;
  const reach = small ? 15 : 10000;
  const steps = Array.from({ length: count }, () => {
    const roll = rand();
    if (roll < 0.1) return 0;
    if (roll < 0.2) return rand() < 0.5 ? length : -length;
    return Math.floor(rand() * (2 * reach + 1)) - reach;
  });
  return [arr, steps, Math.floor(rand() * length)];
}
